from datetime import date, timedelta

_WD = {"MO": 0, "TU": 1, "WE": 2, "TH": 3, "FR": 4, "SA": 5, "SU": 6}


def _parse(start: str) -> date:
    y, m, d = map(int, start.split("-"))
    return date(y, m, d)


def _month_start(year: int, month: int) -> date:
    return date(year, month, 1)


def _next_month(year: int, month: int) -> date:
    if month == 12:
        return date(year + 1, 1, 1)
    return date(year, month + 1, 1)


def _shift_month(year: int, month: int, offset: int) -> tuple[int, int]:
    idx = (month - 1) + offset
    return year + idx // 12, idx % 12 + 1


def recur(start: str, rule: str, count: int) -> list[str]:
    start_d = _parse(start)
    parts = rule.split()
    kind = parts[0]
    k = int(parts[1])
    out: list[str] = []

    if kind == "DAILY":
        cur = start_d
        for _ in range(count):
            out.append(cur.isoformat())
            cur += timedelta(days=k)
        return out

    if kind == "WEEKLY":
        days = sorted(_WD[token] for token in parts[2].split(","))
        monday = start_d - timedelta(days=start_d.weekday())
        week = 0
        while len(out) < count:
            for wd in days:
                dt = monday + timedelta(days=week * 7 + wd)
                if dt >= start_d:
                    out.append(dt.isoformat())
                    if len(out) == count:
                        break
            week += k
        return out

    if kind == "MONTHLY" and len(parts) == 3:
        day_spec = int(parts[2])
        step = 0
        while len(out) < count:
            yy, mm = _shift_month(start_d.year, start_d.month, step * k)
            if day_spec == -1:
                dt = _next_month(yy, mm) - timedelta(days=1)
            else:
                try:
                    dt = date(yy, mm, day_spec)
                except ValueError:
                    dt = None
            if dt is not None and dt >= start_d:
                out.append(dt.isoformat())
            step += 1
        return out

    if kind == "MONTHLY":
        nth = int(parts[2])
        wd = _WD[parts[3]]
        step = 0
        while len(out) < count:
            yy, mm = _shift_month(start_d.year, start_d.month, step * k)
            if nth == -1:
                last = _next_month(yy, mm) - timedelta(days=1)
                dt = last - timedelta(days=(last.weekday() - wd) % 7)
            else:
                first = _month_start(yy, mm)
                dt = first + timedelta(days=(wd - first.weekday()) % 7 + (nth - 1) * 7)
                if dt.month != mm:
                    dt = None
            if dt is not None and dt >= start_d:
                out.append(dt.isoformat())
            step += 1
        return out

    mm_s, dd_s = parts[2].split("-")
    mm, dd = int(mm_s), int(dd_s)
    step = 0
    while len(out) < count:
        yy = start_d.year + step * k
        try:
            dt = date(yy, mm, dd)
        except ValueError:
            dt = None
        if dt is not None and dt >= start_d:
            out.append(dt.isoformat())
        step += 1
    return out
